begin;
create extension if not exists pgtap with schema extensions;
select plan(16);
insert into auth.users(id,email) values ('10000000-0000-4000-8000-000000000003','case@test.invalid');
insert into public.workspaces(id,name) values ('20000000-0000-4000-8000-000000000003','Case test');
insert into public.workspace_members values ('20000000-0000-4000-8000-000000000003','10000000-0000-4000-8000-000000000003','owner',now());
create temporary table test_cases(result jsonb);
grant all on test_cases to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select throws_ok($$select public.save_case_revision('20000000-0000-4000-8000-000000000003','{"title":"poison"}')$$,'23514',null,'incomplete case rejected at persistence boundary');
select is((select count(*) from public.cases where workspace_id='20000000-0000-4000-8000-000000000003'),0::bigint,'invalid case leaves no poisoned record');
insert into test_cases values(public.save_case_revision('20000000-0000-4000-8000-000000000003','{"title":"Release","template":"product_delivery","outcome":"unknown","problem":"Risk","context":"Team","constraints":"No downtime","approach":"Canary","observedOutcome":"Unknown","lessons":"Monitor","deliverable":"Feature","changeScope":"Checkout","deploymentConditions":"Rollback","conceptIds":[],"sources":[]}'));
select throws_ok($$select public.save_case_revision('20000000-0000-4000-8000-000000000003',(select jsonb_set(content,'{title}','"   "') from public.case_revisions limit 1))$$,'23514',null,'whitespace title cannot poison reads');
select throws_ok($$select public.save_case_revision('20000000-0000-4000-8000-000000000003',(select jsonb_set(content,'{sources}','[{"label":"invalid","url":"ftp://example.com"}]') from public.case_revisions limit 1))$$,'23514',null,'non-HTTP source cannot poison reads');
select is((select count(*) from public.cases),1::bigint,'case saved');
select is((select published_revision_id from public.cases),null::uuid,'pending revision is not published');
select throws_ok($$select public.publish_case_revision((select (result->>'revisionId')::uuid from test_cases),'[]','gemini-embedding-2',1536)$$,'P0001','Incomplete index','incomplete indexing cannot publish');
select is((select count(*) from public.case_sections),0::bigint,'failed index creates no partial sections');
select public.publish_case_revision((select (result->>'revisionId')::uuid from test_cases),(select jsonb_agg(jsonb_build_object('key',key,'text',value,'embedding',to_jsonb(array_prepend(1::float8,array_fill(0::float8,array[1535]))))) from public.case_revisions,jsonb_each_text(content) where key in ('problem','context','constraints','approach','observedOutcome','lessons','deliverable','changeScope','deploymentConditions')),'gemini-embedding-2',1536);
select is((select count(*) from public.case_sections),9::bigint,'all sections indexed');
select is((select index_state from public.case_revisions),'ready','index is ready');
select public.publish_case_revision((select (result->>'revisionId')::uuid from test_cases),'[]','gemini-embedding-2',1536);
select is((select count(*) from public.case_sections),9::bigint,'ready retry is idempotent');
select public.save_case_revision('20000000-0000-4000-8000-000000000003',(select content from public.case_revisions limit 1),(select id from public.cases));
select is((select published_revision_id from public.cases),(select (result->>'revisionId')::uuid from test_cases),'pending edit preserves published revision');
select throws_ok($$update public.case_revisions set content='{}'$$,'42501',null,'clients cannot mutate revision content');
select public.archive_case((select id from public.cases));
select is((select lifecycle from public.cases),'archived','archive changes lifecycle');
select throws_ok($$select public.save_case_revision('20000000-0000-4000-8000-000000000004','{}')$$,'42501',null,'forged workspace rejected');
reset role;
update public.case_revisions set index_state='failed' where index_state='pending';
select throws_ok($$update public.case_revisions set content='{}'$$,'P0001','Immutable revision','revision trigger prevents content edits');
select * from finish();
rollback;
